// Auto-generated by scripts/build-dashboard.js — Do not edit manually
const HTML_BASE64 = "";

export interface RenderDashboardOptions {
  clientId?: string;
  apiBaseUrl?: string;
}

export function renderDashboardHtml(options?: string | RenderDashboardOptions): string {
  let content = "";
  if (typeof Buffer !== "undefined") {
    content = Buffer.from(HTML_BASE64, "base64").toString("utf-8");
  } else {
    const binary = atob(HTML_BASE64);
    const bytes = new Uint8Array(binary.length);
    for (let i = 0; i < binary.length; i++) {
      bytes[i] = binary.charCodeAt(i);
    }
    content = new TextDecoder().decode(bytes);
  }

  const clientId = typeof options === "string" ? options : options?.clientId;
  const apiBaseUrl = typeof options === "object" ? options?.apiBaseUrl : undefined;

  let scriptTags = "";
  if (clientId) {
    scriptTags += '  <script>window.GOOGLE_WEB_CLIENT_ID = "' + clientId + '";</script>\n';
  }
  if (apiBaseUrl) {
    scriptTags += '  <script>window.API_BASE_URL = "' + apiBaseUrl + '";</script>\n';
  }

  if (scriptTags) {
    content = content.replace('</head>', scriptTags + '</head>');
  }

  return content;
}
